package com.secretshield;
import java.util.*;
import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.http.MediaType;import org.springframework.security.crypto.password.PasswordEncoder;
import com.secretshield.entity.*;import com.secretshield.repository.*;import com.secretshield.security.JwtService;import com.secretshield.service.*;import com.secretshield.support.PostgresApiTest;
import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class ScanManagementIT extends PostgresApiTest {
 @Autowired UserRepository users;@Autowired ProjectRepositoryRepository repos;@Autowired ScanRepository scans;@Autowired CiCredentialRepository credentials;@Autowired JwtService tokens;@Autowired PasswordEncoder encoder;@Autowired ScanService scanService;
 private User user(String n,UserRole r){return users.saveAndFlush(User.builder().username(n).email(n+"@example.invalid").password("hash").role(r).build());}
 private ProjectRepository repo(User u,String n,boolean active){return repos.saveAndFlush(ProjectRepository.builder().owner(u).githubOwner("demo").githubName(n).canonicalUrl("https://github.com/demo/"+n).defaultBranch("main").active(active).build());}
 private String bearer(User u){return "Bearer "+tokens.generateToken(u.getEmail(),u.getRole().name());}
 private Map<String,Object> manual(){return Map.of("branch","main","commitSha","0123456789abcdef0123456789abcdef01234567");}
 @Test void ownerCreatesListsFiltersAndReadsManualScan()throws Exception{var u=user("scan-owner",UserRole.DEVELOPER);var r=repo(u,"scan",true);var created=mvc.perform(post("/api/repositories/{id}/scans",r.getId()).header("Authorization",bearer(u)).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsBytes(manual()))).andExpect(status().isCreated()).andExpect(jsonPath("$.trigger").value("MANUAL")).andExpect(jsonPath("$.status").value("QUEUED")).andExpect(jsonPath("$.runId").value(org.hamcrest.Matchers.nullValue())).andReturn();String id=json.readTree(created.getResponse().getContentAsString()).get("id").asText();mvc.perform(get("/api/repositories/{id}/scans?status=QUEUED&branch=main&size=1",r.getId()).header("Authorization",bearer(u))).andExpect(status().isOk()).andExpect(jsonPath("$.totalElements").value(1));mvc.perform(get("/api/repositories/{id}/scans/{scanId}",r.getId(),id).header("Authorization",bearer(u))).andExpect(status().isOk()).andExpect(jsonPath("$.id").value(id));}
 @Test void inactiveAndInvalidManualScansAreRejected()throws Exception{var u=user("inactive-scan",UserRole.DEVELOPER);var r=repo(u,"inactive",false);mvc.perform(post("/api/repositories/{id}/scans",r.getId()).header("Authorization",bearer(u)).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsBytes(manual()))).andExpect(status().isConflict());var active=repo(u,"active",true);mvc.perform(post("/api/repositories/{id}/scans",active.getId()).header("Authorization",bearer(u)).contentType(MediaType.APPLICATION_JSON).content("{\"branch\":\"../bad\",\"commitSha\":\"BAD\"}")).andExpect(status().isBadRequest());assertEquals(0,scans.count());}
 @Test void ownershipAndNestedRepositoryIdentityAreEnforced()throws Exception{var a=user("scan-a",UserRole.DEVELOPER);var b=user("scan-b",UserRole.DEVELOPER);var ra=repo(a,"a",true);var rb=repo(b,"b",true);var s=scans.saveAndFlush(Scan.builder().repository(ra).branch("main").commitSha("0123456789abcdef0123456789abcdef01234567").trigger(ScanTrigger.MANUAL).status(ScanStatus.QUEUED).build());mvc.perform(get("/api/repositories/{id}/scans",ra.getId()).header("Authorization",bearer(b))).andExpect(status().isForbidden());mvc.perform(get("/api/repositories/{id}/scans/{scan}",rb.getId(),s.getId()).header("Authorization",bearer(user("scan-admin",UserRole.ADMIN)))).andExpect(status().isNotFound());}
 @Test void credentialIsShownOnceHashedScopedAndRevocable()throws Exception{var u=user("credential-owner",UserRole.DEVELOPER);var r=repo(u,"credential",true);var issued=mvc.perform(post("/api/repositories/{id}/ci-credentials",r.getId()).header("Authorization",bearer(u)).contentType(MediaType.APPLICATION_JSON).content("{}")).andExpect(status().isCreated()).andExpect(jsonPath("$.credential").isString()).andReturn();var node=json.readTree(issued.getResponse().getContentAsString());String raw=node.get("credential").asText();long id=node.get("id").asLong();var stored=credentials.findById(id).orElseThrow();assertNotEquals(raw,stored.getSecretHash());assertTrue(encoder.matches(raw.substring(raw.lastIndexOf('.')+1),stored.getSecretHash()));mvc.perform(post("/api/repositories/{repo}/ci-credentials/{id}/revoke",r.getId(),id).header("Authorization",bearer(u))).andExpect(status().isNoContent());mvc.perform(post("/api/repositories/{repo}/ci-credentials/{id}/revoke",r.getId(),id).header("Authorization",bearer(u))).andExpect(status().isNoContent());assertNotNull(credentials.findById(id).orElseThrow().getRevokedAt());}
 @Test void cleanIngestionIsIdempotentAndConflictingReplayIs409()throws Exception{var u=user("ci-owner",UserRole.DEVELOPER);var r=repo(u,"ci",true);String credential=issue(u,r);Map<String,Object> body=ci("CLEAN",List.of(),null);var first=ciPost(r,credential,body).andExpect(status().isCreated()).andExpect(jsonPath("$.status").value("CLEAN")).andReturn();String id=json.readTree(first.getResponse().getContentAsString()).get("id").asText();ciPost(r,credential,body).andExpect(status().isOk()).andExpect(jsonPath("$.id").value(id));var conflict=new HashMap<>(body);conflict.put("scannerVersion","9.9.9");ciPost(r,credential,conflict).andExpect(status().isConflict());assertEquals(1,scans.count());}
 @Test void findingsAndFailuresRemainDistinctAndPayloadIsSanitized()throws Exception{var u=user("result-owner",UserRole.DEVELOPER);var r=repo(u,"results",true);String c=issue(u,r);ciPost(r,c,ci("FINDINGS_DETECTED",List.of(Map.of("ruleId","synthetic-low","filePath","config/demo.txt","line",2,"sanitizedDescription","Synthetic metadata only")),null)).andExpect(status().isCreated()).andExpect(jsonPath("$.status").value("FINDINGS_DETECTED"));var bad=ci("CLEAN",List.of(Map.of("ruleId","x","filePath","../secret","line",1,"sanitizedDescription","x")),null);ciPost(r,c,bad).andExpect(status().isBadRequest());var failed=ci("FAILED",List.of(),"TOOL_ERROR");failed.put("runAttempt",2);ciPost(r,c,failed).andExpect(status().isCreated()).andExpect(jsonPath("$.failureCode").value("TOOL_ERROR"));assertEquals(2,scans.count());}
 @Test void invalidRevokedWrongScopeAndInteractiveCredentialsAre401()throws Exception{var u=user("scope-owner",UserRole.DEVELOPER);var r1=repo(u,"scope1",true);var r2=repo(u,"scope2",true);String c=issue(u,r1);ciPost(r2,c,ci("CLEAN",List.of(),null)).andExpect(status().isUnauthorized());mvc.perform(post("/api/ci/repositories/{id}/scan-results",r1.getId()).header("Authorization",bearer(u)).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsBytes(ci("CLEAN",List.of(),null)))).andExpect(status().isUnauthorized());var row=credentials.findAll().getFirst();row.setRevokedAt(java.time.LocalDateTime.now(java.time.ZoneOffset.UTC));credentials.saveAndFlush(row);ciPost(r1,c,ci("CLEAN",List.of(),null)).andExpect(status().isUnauthorized());}
 @Test void machinePayloadOverOneMiBIs413()throws Exception{var u=user("large-owner",UserRole.DEVELOPER);var r=repo(u,"large",true);String c=issue(u,r);String large="x".repeat(1024*1024+1);mvc.perform(post("/api/ci/repositories/{id}/scan-results",r.getId()).header("X-Secret-Shield-Credential",c).contentType(MediaType.APPLICATION_JSON).content(large)).andExpect(status().isPayloadTooLarge()).andExpect(jsonPath("$.code").value("PAYLOAD_TOO_LARGE"));assertEquals(0,scans.count());}
 private String issue(User u,ProjectRepository r)throws Exception{var result=mvc.perform(post("/api/repositories/{id}/ci-credentials",r.getId()).header("Authorization",bearer(u)).contentType(MediaType.APPLICATION_JSON).content("{}")).andExpect(status().isCreated()).andReturn();return json.readTree(result.getResponse().getContentAsString()).get("credential").asText();}
 private Map<String,Object> ci(String status,List<?> findings,String failure){var m=new HashMap<String,Object>();m.put("runId","run-100");m.put("runAttempt",1);m.put("commitSha","0123456789abcdef0123456789abcdef01234567");m.put("branch","main");m.put("trigger","CI_PUSH");m.put("scannerVersion","8.0.0");m.put("status",status);m.put("findings",findings);if(failure!=null)m.put("failureCode",failure);return m;}
 private org.springframework.test.web.servlet.ResultActions ciPost(ProjectRepository r,String c,Object b)throws Exception{return mvc.perform(post("/api/ci/repositories/{id}/scan-results",r.getId()).header("X-Secret-Shield-Credential",c).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsBytes(b)));}
}
